contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: send `amount` wei to c.go and assert owner unchanged
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");

        // observe owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        // call go on c, forwarding `amount` Wei
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe owner after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General rule: c.owner does not change regardless of amount or whether the external call reverted
        assert(ownerBefore == ownerAfter);
    }

    // allow receiving Ether if forwarded to this contract in some paths
    receive() external payable {}
}

